void FocusPopupView::released(void*p){auto*b=static_cast<Binding*>(p);auto*v=b->self;delete b;v->drop();}
void FocusPopupView::event(void*p,Event e,double){auto*b=static_cast<Binding*>(p);auto*v=b->self;Scope guard(v);if(e==Event::Destroy){if(b->index==-1)v->root_=nullptr;else v->broken_=true;v->finished_=true;}else v->handle(b->index);}
void FocusPopupView::signal(void*p){auto*b=static_cast<Binding*>(p);auto*v=b->self;Scope guard(v);v->handle(b->index);}
bool FocusPopupView::bind(void*o,Event e,int i){auto*b=new(std::nothrow)Binding(this,i);if(!b)return false;retain();if(api_.listen(api_.context,o,e,event,b,released))return true;released(b);return false;}
bool FocusPopupView::watch(void*o,const char*n,int i,int slot){auto*b=new(std::nothrow)Binding(this,i);if(!b)return false;retain();watches_[slot]=signal_watch(signals_,o,root_,n,signal,b,released);if(watches_[slot])return true;released(b);return false;}
bool FocusPopupView::selectable(int i)const{return live()&&!finished_&&!latched_&&!dispatching_&&state_.source.valid&&state_.source.selectable&&state_.pending<0&&i>=0&&i<3&&state_.source.allowed[i];}
void FocusPopupView::accept(){if(!selectable(selected_)||!choose_)return;Scope guard(this);latched_=true;sawPending_=false;dispatching_=true;bool ok=choose_(context_,selected_);dispatching_=false;if(!ok)latched_=false;if(live()&&!finished_)refresh();}
void FocusPopupView::abort(){if(!live()||finished_||dispatching_)return;Scope guard(this);applied();if(live()&&abort_){dispatching_=true;abort_(context_);dispatching_=false;}}
void FocusPopupView::handle(int i){if(!live()||finished_||dispatching_)return;if(i==-3){abort();return;}if(i==-2){if(touch_)abort();return;}if(i>=0&&i<3&&touch_&&selectable(i)){selected_=i;accept();}}
bool FocusPopupView::refresh(){if(!live()||finished_)return false;Scope guard(this);auto c=api_.context;double sx=style_.scaleX,sy=style_.scaleY,s=style_.scale,pw=672*sx,ph=378*sy,top=176*sy,x=(width_-pw)/2,ch=ph-style_.headerHeight;
 auto rect=[&](void*o,double a,double b,double w,double h){if(!live())return false;api_.rect(c,o,a,b,w,h);return live();};auto number=[&](void*o,const char*n,double v){return live()&&stock_set_number(stock_,o,n,v)&&live();};auto boolean=[&](void*o,const char*n,bool v){return live()&&stock_set_bool(stock_,o,n,v)&&live();};auto text=[&](void*o,const char*n,const char16_t*v){return live()&&stock_set_text(stock_,o,n,v)&&live();};
 if(!rect(root_,0,0,width_,height_)||!rect(content_,0,0,pw,ch)||!text(root_,"heading",style_.heading)||!number(root_,"contentWidth",pw)||!number(root_,"contentHeight",ph)||!number(root_,"popupTopMargin",top))return false;
 const char16_t*icons[]={u"image://svg/ic_controlscreen_focus_mode_AF-S",u"image://svg/ic_controlscreen_focus_mode_AF-C",u"image://svg/ic_controlscreen_focus_mode_MF"};double iw=(pw-48*sx)/3;
 for(int i=0;i<3;i++){auto*o=choice_[i];bool enabled=selectable(i);if(!rect(o,24*sx+i*iw,48*sy,iw,210*sy)||!number(o,"highlightWidth",146*sx)||!number(o,"highlightHeight",96*sy)||!boolean(o,"focus",i==selected_)||!boolean(o,"forceHighlight",i==selected_)||!text(o,"text",focus_text(state_.source.language,i))||!number(o,"textPixelSize",28.8*s)||!number(o,"textTopMargin",12.8*sy))return false;
  api_.enabled(c,o,enabled&&touch_);if(!live())return false;api_.opacity(c,o,enabled?1:.4);if(!live()||!text(o,"source",icons[i]))return false;
 }
 if(!rect(status_,0,ch-20*sy-28*s,pw,28*s))return false;api_.text(c,status_,state_.pending>=0||latched_?focus_text(state_.source.language,3):state_.failed?focus_text(state_.source.language,4):u"",22*s,1);if(!live())return false;api_.color(c,status_,style_.foreground,true);if(!live())return false;
 if(!rect(outside_[0],0,0,width_,top)||!rect(outside_[1],0,top+ph,width_,height_-top-ph)||!rect(outside_[2],0,top,x,ph)||!rect(outside_[3],x+pw,top,width_-x-pw,ph))return false;for(auto*o:outside_){api_.enabled(c,o,touch_);if(!live())return false;}return true;
}
bool FocusPopupView::update(const FocusPopupState&s,const FocusPopupStyle&style,double w,double h,bool touch){if(!live()||finished_)return false;Scope guard(this);
 bool ok=std::isfinite(w)&&std::isfinite(h)&&w>0&&h>0&&w<=16384&&h<=16384&&std::isfinite(style.scaleX)&&std::isfinite(style.scaleY)&&std::isfinite(style.scale)&&style.scaleX>0&&style.scaleY>0&&style.scale>0&&style.scale<=8&&std::isfinite(style.headerHeight)&&style.headerHeight>0&&style.headerHeight<378*style.scaleY&&672*style.scaleX<=w&&554*style.scaleY<=h&&style.heading;
 size_t n=0;if(ok){while(n<256&&style.heading[n])++n;ok=n<256;}if(!ok){applied();return false;}
 if(s.source.mode!=state_.source.mode||s.source.valid!=state_.source.valid||s.selected!=state_.selected)selected_=s.selected>=0&&s.selected<3?s.selected:-1;
 if(s.pending>=0)sawPending_=true;if(s.failed||s.closed||(sawPending_&&s.pending<0))latched_=false;
 state_=s;style_=style;for(size_t i=0;i<=n;i++)heading_[i]=style.heading[i];style_.heading=heading_;width_=w;height_=h;touch_=touch;if(s.closed){applied();return true;}ok=refresh();if(!ok&&live())applied();return ok;
}
bool FocusPopupView::key(FocusKey k){if(!live()||finished_||dispatching_)return false;Scope guard(this);if(k==FocusKey::Abort){abort();return true;}if(k==FocusKey::Accept){accept();return true;}if(k!=FocusKey::Previous&&k!=FocusKey::Next)return false;int step=k==FocusKey::Next?1:-1,start=selected_<0?(step>0?-1:3):selected_;for(int i=start+step;i>=0&&i<3;i+=step)if(selectable(i)){selected_=i;break;}refresh();return true;}
void FocusPopupView::applied(){if(!live()||finished_)return;Scope guard(this);finished_=true;stock_set_text(stock_,root_,"state",u"finish");}
FocusPopupView*FocusPopupView::create(ViewApi a,StockProfile s,SignalProfile g,FacePopupProfile l,void*co,void*parent,bool(*choose)(void*,int),void(*abort)(void*),void*ctx){
 if(!co||!parent||!choose||!abort||!l.listType||!a.create||!a.destroy||!a.rect||!a.color||!a.text||!a.visible||!a.enabled||!a.opacity||!a.name||!a.layer||!a.listen)return nullptr;
 auto*v=new(std::nothrow)FocusPopupView(a,s,g);if(!v)return nullptr;v->choose_=choose;v->abort_=abort;v->context_=ctx;v->root_=stock_create(s,StockKind::Popover,co,parent);if(!v->root_){delete v;return nullptr;}if(!v->bind(v->root_,Event::Destroy,-1)){a.destroy(a.context,v->root_);delete v;return nullptr;}auto fail=[&](){v->close();return static_cast<FocusPopupView*>(nullptr);};a.name(a.context,v->root_,"X2dNativeFocusPopup");if(!v->live())return fail();a.layer(a.context,v->root_,2100,false);if(!v->live()||!stock_set_bool(s,v->root_,"handleDefaultKeys",false)||!v->live())return fail();v->content_=a.create(a.context,Kind::Item,v->root_);if(!v->live()||!v->content_||!v->bind(v->content_,Event::Destroy,-4))return fail();a.name(a.context,v->content_,"X2dFocusContent");if(!v->live())return fail();v->status_=a.create(a.context,Kind::Text,v->content_);if(!v->live()||!v->status_||!v->bind(v->status_,Event::Destroy,-4))return fail();a.name(a.context,v->status_,"X2dFocusStatus");if(!v->live())return fail();
 auto attach=[&](void*o,void*item){auto variant=s.property(o,"content");bool ok=false;if(s.variant_convert(&variant,{l.listType})){auto*list=static_cast<FacePopupList*>(s.variant_data(&variant));if(list&&list->object&&list->append&&list->count&&list->at&&list->count(list)==0){list->append(list,item);ok=v->live()&&list->count(list)==1&&list->at(list,0)==item;}}s.variant_destroy(&variant);return ok;};if(!attach(v->root_,v->content_))return fail();
 for(int i=0;i<3;i++){auto*o=stock_create(s,StockKind::FramedImage,co,v->content_);v->choice_[i]=o;if(!v->live()||!o||!v->bind(o,Event::Destroy,-4))return fail();char name[48];snprintf(name,sizeof name,"X2dFocusChoice%d",i);a.name(a.context,o,name);if(!v->live()||!stock_set_bool(s,o,"acceptKeys",false)||!v->live()||!v->watch(o,"pressed()",i,i))return fail();v->icons_[i]=stock_get_object(s,o,"image");if(!v->live()||!v->icons_[i]||!v->bind(v->icons_[i],Event::Destroy,-4))return fail();snprintf(name,sizeof name,"X2dFocusIcon%d",i);a.name(a.context,v->icons_[i],name);if(!v->live())return fail(); }
 for(int i=0;i<4;i++){auto*o=a.create(a.context,Kind::Mouse,v->root_);v->outside_[i]=o;if(!v->live()||!o||!v->bind(o,Event::Destroy,-4)||!v->bind(o,Event::Click,-2))return fail();char name[48];snprintf(name,sizeof name,"X2dFocusOutside%d",i);a.name(a.context,o,name);if(!v->live())return fail();a.layer(a.context,o,101,false);if(!v->live())return fail();}if(!v->watch(v->root_,"closePopup()",-3,3))return fail();return v;
}
void FocusPopupView::close(){if(closed_)return;closed_=true;finished_=true;for(auto*&w:watches_){auto*p=w;w=nullptr;signal_unwatch(p);}if(root_){auto*p=root_;root_=nullptr;api_.destroy(api_.context,p);}drop();}
